mapper.select:
SELECT p.id, p.category_id, p.title, p.summary, p.content, p.tags, p.key_points, p.learning_directions, p.author_id, p.is_published, p.view_count, p.is_indexed_in_rag, p.indexed_at, p.created_at, p.updated_at, c.name AS category_name, c.section AS category_section FROM posts p JOIN categories c ON p.category_id = c.id
AND c.section = #{section}
AND p.category_id = #{categoryId}
ORDER BY p.id DESC
